/* ---------- Feedback sheet ---------- */
.fbx{display:flex;flex-direction:column;gap:8px}
.fbx-bar{display:flex;align-items:center;gap:2px;margin-left:-6px}
.fbx-bar .ib svg{transition:transform .45s var(--ease)}
.fbx-bar .ib.on svg{transform:scale(1.12) rotate(-8deg)}
.fbx-dn.on{background:var(--bad-bg);color:var(--bad)}
.fbx-st{font-size:12.5px;margin-left:6px}
.fbx-box>div{margin-inline:-16px;padding-inline:16px}
.fbx-in{padding:14px;display:flex;flex-direction:column;gap:10px;margin:4px 0 18px}
.fbx-q{font-size:13.5px;font-weight:500}
.fbx-ch{display:flex;flex-wrap:wrap;gap:6px}
.fbx-ch .chip.on{background:var(--sel);color:var(--accent);box-shadow:none}
.fbx-ta{width:100%;resize:none;border:0;outline:0;border-radius:12px;background:var(--chip);padding:9px 12px;font:inherit;font-size:13px;color:var(--fg);transition:box-shadow .3s}
.fbx-ta:focus,.fbx-ta.typing{box-shadow:0 0 0 2px var(--accent-bg),inset 0 0 0 1px var(--accent)}
.fbx-ta::placeholder{color:var(--muted)}
.fbx-f{display:flex;align-items:center;gap:6px}
.fbx-n{font-size:12px;flex:1;min-width:0}
.fbx-thx{display:flex;align-items:center;gap:8px;font-size:13px;padding:10px 12px;border-radius:12px;background:var(--ok-bg);color:var(--ok)}
@media (max-width:480px){.fbx-n{display:none}}

DM.def('feedback-sheet', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{up}', I('up-thumb')).replace('{dn}', I('down-thumb'));
  const up = $('.fbx-up', r), dn = $('.fbx-dn', r), box = $('.fbx-box', r), st = $('.fbx-st', r), go = $('.fbx-go', r), ta = $('.fbx-ta', r), chips = $$('.fbx-ch .chip', r);
  const ready = () => go.disabled = !(chips.some(x => x.classList.contains('on')) || ta.value.trim());
  chips.forEach(ch => ch.onclick = () => { ch.classList.toggle('on'); ready(); });
  ta.oninput = ready;
  up.onclick = () => { const on = !up.classList.contains('on'); up.classList.toggle('on', on); dn.classList.remove('on'); box.classList.add('shut'); swap(st, on ? 'Thanks, noted' : ''); };
  // the demo opens the sheet without taking the focus from wherever you are on the page
  const down = focus => { const on = !dn.classList.contains('on'); dn.classList.toggle('on', on); up.classList.remove('on'); box.classList.toggle('shut', !on); swap(st, ''); if (on && focus) c.later(350, () => ta.focus({ preventScroll:true })); };
  dn.onclick = e => down(e.isTrusted);
  $('.fbx-x', r).onclick = () => { box.classList.add('shut'); dn.classList.remove('on'); };
  go.onclick = () => c.run(async () => {
    go.innerHTML = '<span class="spin"></span>'; await c.wait(800);
    box.classList.add('shut'); await c.wait(300);
    const n = chips.filter(x => x.classList.contains('on')).length;
    const thx = html(`<div class="fbx-thx">${I('ok')}<span>Thanks. The agent will ${n ? 'avoid this' : 'use this'} next time in this project.</span></div>`);
    r.firstElementChild.appendChild(thx); enter(thx); swap(st, 'Feedback sent');
  });
  /* once it has entered, it rates the answer down and fills in the sheet by itself. Anything you do inside it takes over */
  let auto = true; const mine = e => { if (e.isTrusted){ auto = false; ta.classList.remove('typing'); } };
  c.on(r, 'pointerdown', mine, true); c.on(r, 'keydown', mine, true);
  const beat = async ms => { await c.wait(ms); if (!auto) throw 'stop'; };
  c.run(async () => {
    await beat(1500); down(false);
    await beat(1000); chips[1].click();
    await beat(700); ta.classList.add('typing');
    for (const ch of 'Keep our 8px spacing scale'){ ta.value += ch; ready(); await beat(34 + Math.random() * 40); }
    await beat(650); ta.classList.remove('typing'); go.click();
  });
});
